import math

def fermi_dirac(E, E_F, T):
    k = 8.617e-5  # Boltzmann constant in eV/K
    if T == 0:
        return 1.0 if E < E_F else 0.0
    exponent = (E - E_F) / (k * T)
    return 1.0 / (1.0 + math.exp(exponent))

# Example: E = 0.6 eV, E_F = 0.5 eV, T = 300 K
prob = fermi_dirac(0.6, 0.5, 300)
print(f"Occupation probability: {prob:.4f}")

