import numpy as np
def dos_2d_constant(m_star):
    hbar = 1.0545718e-34
    pi = np.pi
    return m_star / (pi * hbar**2)

def carey_foster(R1, Rv, Rv_prime):
    """Return Rx = R1 * (Rv / Rv_prime)"""
    return R1 * (Rv / Rv_prime)

